"""Minimal standard-library client for private text prompts to OpenAI.

Set OPENAI_API_KEY in your environment, then:

    from openai_client import send_prompt

    text = send_prompt("Write a concise status update.")

This module intentionally does not log prompts, write request/response data to
disk, or use third-party packages. Requests default to ``store=False`` so the
Responses API is asked not to persist the response.
"""

from __future__ import annotations

import json
import os
import ssl
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from typing import Any, Mapping


DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4.1-mini")


class OpenAIClientError(Exception):
    """Base exception raised by this module."""


class OpenAIConfigurationError(OpenAIClientError):
    """Raised when the client cannot be configured safely."""


class OpenAIAPIError(OpenAIClientError):
    """Raised when the API returns a non-2xx response."""

    def __init__(
        self,
        status_code: int,
        message: str,
        *,
        request_id: str | None = None,
        body: Mapping[str, Any] | str | None = None,
    ) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.request_id = request_id
        self.body = body


@dataclass(frozen=True)
class OpenAIClient:
    """Small Responses API client that uses only Python's standard library."""

    api_key: str | None = field(default=None, repr=False)
    model: str = DEFAULT_MODEL
    base_url: str = DEFAULT_BASE_URL
    timeout: float = 60.0
    allow_env_proxies: bool = False

    def __post_init__(self) -> None:
        key = self.api_key or os.environ.get("OPENAI_API_KEY")
        if not key:
            raise OpenAIConfigurationError(
                "Set OPENAI_API_KEY or pass api_key=... to OpenAIClient."
            )
        object.__setattr__(self, "api_key", key)
        object.__setattr__(self, "base_url", self.base_url.rstrip("/"))

    def create_response(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        store: bool = False,
        metadata: Mapping[str, str] | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Send a text prompt to the Responses API and return the full JSON body."""

        if not isinstance(prompt, str) or not prompt:
            raise ValueError("prompt must be a non-empty string")

        payload: dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": store,
        }
        if instructions is not None:
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens
        if temperature is not None:
            payload["temperature"] = temperature
        if metadata is not None:
            payload["metadata"] = dict(metadata)
        if extra:
            payload.update(extra)

        return self._post_json("/responses", payload)

    def send_prompt(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        store: bool = False,
        metadata: Mapping[str, str] | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> str:
        """Send a prompt and return the assistant's text output."""

        response = self.create_response(
            prompt,
            model=model,
            instructions=instructions,
            max_output_tokens=max_output_tokens,
            temperature=temperature,
            store=store,
            metadata=metadata,
            extra=extra,
        )
        return extract_output_text(response)

    def _post_json(self, path: str, payload: Mapping[str, Any]) -> dict[str, Any]:
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        request = urllib.request.Request(
            f"{self.base_url}{path}",
            data=data,
            method="POST",
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "application/json",
                "User-Agent": "stdlib-openai-client/1.0",
            },
        )

        https_handler = urllib.request.HTTPSHandler(context=ssl.create_default_context())
        opener = urllib.request.build_opener(
            urllib.request.ProxyHandler({}),
            https_handler,
        )
        if self.allow_env_proxies:
            opener = urllib.request.build_opener(https_handler)

        try:
            with opener.open(request, timeout=self.timeout) as response:
                return _loads_json(response.read())
        except urllib.error.HTTPError as exc:
            request_id = exc.headers.get("x-request-id")
            body = _loads_json(exc.read(), fallback_to_text=True)
            message = _error_message(body) or f"OpenAI API request failed: HTTP {exc.code}"
            raise OpenAIAPIError(
                exc.code,
                message,
                request_id=request_id,
                body=body,
            ) from exc
        except urllib.error.URLError as exc:
            raise OpenAIClientError(f"OpenAI API request failed: {exc.reason}") from exc


def send_prompt(prompt: str, **kwargs: Any) -> str:
    """Convenience wrapper around ``OpenAIClient().send_prompt(...)``."""

    return OpenAIClient().send_prompt(prompt, **kwargs)


def create_response(prompt: str, **kwargs: Any) -> dict[str, Any]:
    """Convenience wrapper around ``OpenAIClient().create_response(...)``."""

    return OpenAIClient().create_response(prompt, **kwargs)


def extract_output_text(response: Mapping[str, Any]) -> str:
    """Extract text from a Responses API response body.

    The API commonly returns an ``output_text`` convenience field. The fallback
    handles the structured ``output[].content[]`` format.
    """

    output_text = response.get("output_text")
    if isinstance(output_text, str):
        return output_text

    parts: list[str] = []
    output = response.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping):
                continue
            content = item.get("content")
            if not isinstance(content, list):
                continue
            for block in content:
                if not isinstance(block, Mapping):
                    continue
                text = block.get("text")
                if isinstance(text, str):
                    parts.append(text)

    if parts:
        return "".join(parts)
    raise OpenAIClientError("Response did not contain text output.")


def _loads_json(data: bytes, *, fallback_to_text: bool = False) -> Any:
    text = data.decode("utf-8", errors="replace")
    if not text and fallback_to_text:
        return ""
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        if fallback_to_text:
            return text
        raise OpenAIClientError("OpenAI API returned invalid JSON.")


def _error_message(body: Mapping[str, Any] | str | None) -> str | None:
    if not isinstance(body, Mapping):
        return body or None
    error = body.get("error")
    if isinstance(error, Mapping):
        message = error.get("message")
        if isinstance(message, str):
            return message
    return None


__all__ = [
    "OpenAIAPIError",
    "OpenAIClient",
    "OpenAIClientError",
    "OpenAIConfigurationError",
    "create_response",
    "extract_output_text",
    "send_prompt",
]

